/** Returns "::uuid" / "::date" / "::timestamptz" for a known column, else "". */
export function castSuffix(table: string, column: string): string {
  const cast = COLUMN_CASTS[`${table}.${column}`];
  return cast ? `::${cast}` : "";
}
